if backoffDuration > 5*time.Minute {
    backoffDuration = 5 * time.Minute
}
instance.BackoffUntil = time.Now().Add(backoffDuration)
```

### D. `DynamicDNSService.updateRecordWithRetry` -- Multiplicative Backoff
**File:** `/home/gperry/Documents/GitHub/KNIRV/KNIRV_NETWORK/packages/KNIRVSERVER/backend/internal/services/dns/dynamic_dns_service.go`

Multiplies delay by `BackoffFactor` (default 2.0) after each failure:
```go
func (dds *DynamicDNSService) updateRecordWithRetry(zoneID string, record cloudflare.DNSRecord) error {
    var lastErr error
    delay := dds.config.RetryDelay  // default 30s
    for attempt := 0; attempt <= dds.config.MaxRetries; attempt++ {
        if attempt > 0 {
            time.Sleep(delay)
            delay = time.Duration(float64(delay) * dds.config.BackoffFactor)
        }
        _, err := dds.dnsManager.UpdateOrCreateDNSRecord(zoneID, record)
        if err == nil { return nil }
        lastErr = err
    }
    return fmt.Errorf("failed after %d attempts: %w", dds.config.MaxRetries+1, lastErr)
}
```

