import "github.com/apache/arrow/go/v14/arrow/flight"

type FlightServer struct {
    flight.BaseFlightServer
    allocator    memory.Allocator
    memorySystem *UnifiedMemorySystem
    logger       *zap.Logger
    server       flight.Server
